import {studentEmotion,reactionEffects} from './student-reaction.js';
import {getDiscipline} from './disciplines.js';
import {weeklyAppearance,renderPortrait} from './appearance.js';
import {miniRoomArt,roomDecorations} from './mini-room.js';
import {recoveryArt} from './recovery-art.js';
export {roomDecorations} from './mini-room.js';
export {labSeason} from './lab-season.js';
const escape=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function researchText(text,state){return state?.professorProfile?.labMode==='dry'?String(text).replace(/예비 실험/g,'예비 계산').replace(/실험실/g,'연구실').replace(/실험 노트/g,'연구 노트').replace(/실험/g,'연구'):text;}
export function supplyLevel(state){if(state.lab.funds<40||state.lab.budget.environment===0)return 'sparse';if(state.lab.funds>=140&&state.lab.budget.environment>=3&&state.lab.equipment>=45)return 'rich';return 'balanced';}
const rect=(x,y,w,h,fill)=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" fill="${fill}"/>`;
export function conferenceHall(state){return (Math.imul((state.creationSeed??state.seed)^(state.month*7919),2654435761)>>>0)%4;}
export function figureType(state){const label=getDiscipline(state.professorProfile.fieldId).label;if(/수학|통계/.test(label))return 'equation';if(/컴퓨터|전산|정보|소프트/.test(label))return 'network';if(/건축|도시|조경/.test(label))return 'plan';if(/토목|교통|환경/.test(label))return 'section';if(/의학|간호|보건|치료|약학/.test(label))return 'survival';if(/생물|생명|바이오/.test(label))return 'bars';if(/화학|재료|고분자|신소재/.test(label))return 'spectrum';if(/지구|지리|천문|대기|해양/.test(label))return 'map';if(/기계|항공|자동차|전기|전자/.test(label))return 'system';return 'curve';}
export function fieldFigure(state){const type=figureType(state);if(type==='plan')return '<g fill="none" stroke="#809b9a" stroke-width="2"><path d="M152 76h175v44H152zM205 76v44M270 76v44M205 98h65M152 96h30M310 76v20"/><path d="M177 80v10h20"/></g>';if(type==='section')return '<g fill="none" stroke="#8d9b98" stroke-width="2"><path d="M145 112h210M163 108l42-30 50 30 50-30 42 30M180 110v14m65-14v14m65-14v14"/></g>';if(type==='survival')return '<path d="M150 75v47h185M155 82h37v8h35v7h38v10h40v8h24" fill="none" stroke="#81a797" stroke-width="2"/>';if(type==='map')return '<g fill="#c0d0bb" stroke="#7e9b99"><path d="M153 78l42-5 21 14 35-12 28 14 44-6 9 28-37 8-27-8-35 7-30-13-28 8z"/></g><path d="M180 93h127M196 78v34m43-28v26m39-24v24" stroke="#edf2e5"/>';if(type==='system')return '<g fill="#d8e4de" stroke="#7f97a5"><rect x="150" y="86" width="44" height="24"/><rect x="229" y="86" width="44" height="24"/><rect x="308" y="86" width="35" height="24"/></g><path d="M194 98h35m44 0h35M325 110v13H172v-13" stroke="#7f97a5" fill="none"/>';if(type==='equation')return '<text x="180" y="102" fill="#58788b" font-size="20">f(x) = Σ aₙxⁿ</text>';if(type==='bars')return [0,1,2,3,4].map(i=>rect(150+i*37,114-i*8,21,10+i*8,'#81a797')).join('');if(type==='network')return '<path d="M154 108L205 81 260 108 320 70M205 81L320 70M154 108L260 108" stroke="#849ab2" stroke-width="2"/>'+[ [154,108],[205,81],[260,108],[320,70] ].map(([x,y])=>rect(x-4,y-4,8,8,'#578a99')).join('');if(type==='spectrum')return '<path d="M140 114h32l9-42 10 42h26l7-19 8 19h25l11-54 12 54h66" fill="none" stroke="#8f83ad" stroke-width="3"/>';return '<path d="M140 111L172 91 205 104 240 75 275 88 310 64 345 83" fill="none" stroke="#81a797" stroke-width="4"/>';}
function roomArt(kind,state,result={},index=0,options={}){
 if(['wet','dry','rest'].includes(kind)&&!(kind==='rest'&&result.destination==='bed'))return miniRoomArt(state,kind,result,index,options);
 const hall=conferenceHall(state),wet=kind==='wet',conference=['conference','defense'].includes(kind),rest=kind==='rest',travel=kind==='travel';
 let art=rect(0,0,600,255,travel?'#b4d8d4':conference?['#dce0f0','#d1e2dc','#e9dfd2','#d5dde8'][hall]:'#d7e4e2')+`<path d="M0 165H600V255H0z" fill="${conference?'#939bb3':'#dfc7a2'}"/><path d="M0 182H600M0 212H600M60 165L20 255M180 165L160 255M420 165L450 255M540 165L590 255" stroke="${conference?'#858da6':'#c9ae88'}" stroke-width="2"/>`;
 if(travel||result.destination==='bed')art=recoveryArt(state,result,index);

 else if(conference){if(hall===1)art+=rect(18,10,30,145,'#789790')+rect(548,10,30,145,'#789790');if(hall===2)art+=rect(15,18,44,132,'#baa58e')+rect(538,18,44,132,'#baa58e');if(hall===3)art+=rect(24,12,32,140,'#5c708d')+rect(538,12,32,140,'#5c708d');art+=rect(95,20,310,119,'#647f9c')+rect(103,28,294,103,'#f7f6ed')+`<text x="250" y="45" text-anchor="middle" fill="#47768b" font-size="11" font-family="sans-serif">${kind==='defense'?'THESIS DEFENSE':result.abroad?'INTERNATIONAL CONFERENCE':'RESEARCH CONFERENCE'}</text><text x="250" y="64" text-anchor="middle" fill="#687d89" font-size="10">${escape(getDiscipline(state.professorProfile.fieldId).label)} · ${state.professorProfile.labMode==='wet'?'Experimental findings':'Models & evidence'}</text>${fieldFigure(state)}`+rect(405,162,90,48,'#b39779')+rect(400,154,100,10,'#806850');for(let i=0;i<(hall===2?6:5);i++)art+=rect(55+i*(hall===2?65:75),212,40,32,['#657c97','#688b80','#9b816e','#5c6b8c'][hall]);if(kind==='defense')for(let i=0;i<3;i++)art+=rect(85+i*65,149,22,22,'#e0b799')+rect(82+i*65,145,28,7,'#48434c')+rect(78+i*65,171,38,30,'#566b88');}
 return `<svg class="pixel-room-art" viewBox="0 0 600 255" aria-hidden="true" preserveAspectRatio="xMidYMid slice"><g shape-rendering="crispEdges">${art}</g></svg>`;
}
export function sceneKind(state,result={actual:'idle'}){if(state.pending?.kind==='thesis'&&result.actual==='idle')return 'defense';if(result.actual==='conference'||result.abroad)return 'conference';if(result.actual==='rest')return 'rest';if(result.actual==='travel')return 'travel';return state.professorProfile.labMode;}
// Standalone outer SVG, including nested portraits/windows, for persistent CV snapshots.
export function renderLabScene(state,result={actual:'idle'},index=0,options={idle:true}){
 const svg=roomArt(sceneKind(state,result),state,result,index,{...options,stock:options.stock??supplyLevel(state)}),height=svg.match(/viewBox="0 0 600 (\d+)"/)?.[1]??'360';
 return svg.replace('<svg ',`<svg xmlns="http://www.w3.org/2000/svg" width="600" height="${height}" `);
}
export function roomScene(state,result={actual:'idle'},index=0,{idle=false}={}){
 const kind=sceneKind(state,result),stock=kind==='wet'?supplyLevel(state):null,label=({wet:'Wet lab · 연구실',dry:'Dry lab · 계산·분석 공간',rest:'잠시 쉬어 가는 방',travel:'연구실 밖의 하루',conference:result.abroad?'해외학회장':'학술대회장',defense:'학위심사실'})[kind];
 const mini=['wet','dry','rest'].includes(kind)&&result.destination!=='bed';
 const expression=studentEmotion(state,result,{idle});
 return `<div class="pixel-room expression-${expression} scene-${kind} ${idle?'scene-idle':'scene-active'}" data-scene="${kind}" data-projection="${mini?'isometric':'front'}" data-expression="${expression}" data-hall="${conferenceHall(state)}" data-figure="${figureType(state)}" data-props="${mini?Object.entries(roomDecorations(state)).filter(([,v])=>typeof v==='boolean'&&v).map(([k])=>k).join(' '):''}"${stock?` data-supply="${stock}"`:''}>${roomArt(kind,state,result,index,{idle,stock:stock??supplyLevel(state)})}<span class="room-label">${escape(label)}${stock?' · '+({rich:'자재가 넉넉하다',balanced:'필요한 자재를 갖췄다',sparse:'자재를 아껴 쓰는 중'})[stock]:''}</span>${mini?'':`<div class="pixel-student expression-${expression} action-${escape(result.actual)}"><svg class="student-reaction-art" viewBox="0 0 320 496" aria-hidden="true"><g transform="translate(160 160) scale(3)">${reactionEffects(expression,index)}</g></svg>${renderPortrait(weeklyAppearance(state,index),'학생 도트 초상화',expression)}</div>`}${kind==='defense'?`<span class="defense-step">${({draft:'초안 준비',presentation:'공개 발표',questions:'질의응답',revision:'수정·보완',verdict:'최종 판정'})[state.pending.step]}</span>`:''}</div>`;
}
export function idleLabScene(state){return `<div class="lab-scene-heading"><strong>${escape(state.name)}의 하루</strong><span>${state.pending?.kind==='thesis'?'중요 일정 · 학위심사':'이번 달의 연구실'}</span></div>${roomScene(state,state.service?.trainingStartMonth===state.month?{actual:'training',outcome:'training'}:{actual:'idle'},0,{idle:true})}<div class="live-scene-status" aria-live="polite">${state.service?.trainingStartMonth===state.month?'겨울방학 군사교육소집 · 학생 지도와 면담은 잠시 중단합니다.':state.pending?.kind==='thesis'?'지금까지의 연구를 설명하고 질문에 답할 시간입니다.':'주별 계획을 합의하면 학생의 한 달이 여기에서 이어집니다.'}</div>`;}
